<script setup lang="ts">
import {computed,reactive,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage,ElMessageBox,type FormInstance} from 'element-plus'
import {api,post,download,type User,type ModuleSpec,type RecordRow} from '../api'
import {required,harvestRules,passwordRules} from '../defense-schema'
import Chart from '../components/Chart.vue'
const props=defineProps<{section:string;user:User;modules:ModuleSpec[]}>(),router=useRouter()
const titles:Record<string,string>={timeline:'地块生长时间轴','environment-rules':'环境阈值与预警',finance:'成本与销售收益','harvest-trace':'采收与产品溯源',guides:'农技种植资料','market-analysis':'市场行情与销售参考',notifications:'消息与待办',reports:'Excel / PDF 报表',account:'修改账号密码'}
const busy=ref(false),error=ref(''),lands=ref<RecordRow[]>([]),growth=ref<RecordRow[]>([]),plot=ref<number>(),batchFilter=ref<number>(),rules=ref<RecordRow[]>([]),harvests=ref<RecordRow[]>([])
type EventRow={key:string;time:string;kind:string;title:string;status:string;demo:boolean;detail:Record<string,unknown>}
type TraceRow={id:number;token:string;published:boolean;stock_id:number;snapshot:{crop:string;batch:string;quantity:number;plot:string;demo:boolean}}
type Guide={crop:string;title:string;scope:string;stages:string[];checks:string[];source_title:string;source:string;note:string}
type Finance={cost:number;sales:number;profit:number;note:string;unallocated_cost:number;unallocated_sales:number;monthly:{month:string;cost:number;sales:number}[];plots:{plot_id:number;title:string;area:number;cost:number;sales:number;profit:number;profit_per_mu:number|null}[]}
const events=ref<EventRow[]>([]),traces=ref<TraceRow[]>([]),guides=ref<Guide[]>([]),todo=ref<{key:string;title:string;module:string;status:string;time:string}[]>([]),finance=ref<Finance>(),market=ref<RecordRow[]>([]),marketTotal=ref(0),year=ref(new Date().getFullYear()),includeDemo=ref(false),reportModule=ref(''),marketKey=ref(''),estimateQty=ref(100)
const ruleForm=ref<FormInstance>(),harvestForm=ref<FormInstance>(),passwordForm=ref<FormInstance>()
const rule=reactive({crop:'',stage:'全部阶段',temperature_min:undefined as number|undefined,temperature_max:undefined as number|undefined,humidity_min:undefined as number|undefined,humidity_max:undefined as number|undefined,soil_min:undefined as number|undefined,soil_max:undefined as number|undefined,basis:''})
const metrics=[{key:'temperature',label:'空气温度（℃）',min:-50,max:70},{key:'humidity',label:'空气相对湿度（%）',min:0,max:100},{key:'soil',label:'土壤湿度（%）',min:0,max:100}] as const
const harvest=reactive({growth_id:undefined as number|undefined,batch:'',date:new Date().toLocaleDateString('sv-SE'),quantity:1,grade:'A'})
const password=reactive({old_password:'',new_password:'',repeat:''})
const selectedGrowth=computed(()=>growth.value.filter(g=>g.data.plot_id===plot.value))
const financeChart=computed(()=>({tooltip:{trigger:'axis' as const},legend:{data:['登记成本','出库销售']},xAxis:{type:'category' as const,data:finance.value?.monthly.map(x=>x.month.slice(5))},yAxis:{type:'value' as const,name:'元'},series:[{name:'登记成本',type:'bar' as const,data:finance.value?.monthly.map(x=>x.cost)},{name:'出库销售',type:'bar' as const,data:finance.value?.monthly.map(x=>x.sales)}]}))
function priceKey(r:RecordRow){return [r.data.crop,r.data.region,r.data.type,r.data.grade].map(v=>v||'未填写').join(' / ')}
const marketOptions=computed(()=>[...new Set(market.value.filter(r=>includeDemo.value||!r.demo).map(priceKey))])
const prices=computed(()=>market.value.filter(r=>priceKey(r)===marketKey.value&&(includeDemo.value||!r.demo)).sort((a,b)=>String(a.data.date).localeCompare(String(b.data.date))))
const latest=computed(()=>prices.value.at(-1)),estimate=computed(()=>Number(latest.value?.data.price||0)*estimateQty.value)
const marketChart=computed(()=>({tooltip:{trigger:'axis' as const},xAxis:{type:'category' as const,data:prices.value.map(r=>String(r.data.date||''))},yAxis:{type:'value' as const,name:'元/kg'},series:[{name:'登记报价',type:'line' as const,data:prices.value.map(r=>Number(r.data.price||0))}]}))
async function guarded(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message;ElMessage.error(error.value)}finally{busy.value=false}}
async function fetchTimeline(){if(!plot.value){events.value=[];return}events.value=await api(`/plots/${plot.value}/timeline${batchFilter.value?'?growth_id='+batchFilter.value:''}`)}
async function load(){await guarded(async()=>{const s=props.section;if(['timeline','environment-rules','harvest-trace'].includes(s)){lands.value=(await api<{items:RecordRow[]}>('/records/lands?size=200')).items;growth.value=(await api<{items:RecordRow[]}>('/records/growth?size=200')).items;if(!lands.value.some(l=>l.id===plot.value))plot.value=lands.value[0]?.id;if(s==='timeline')await fetchTimeline();if(s==='environment-rules')rules.value=await api('/environment-rules');if(s==='harvest-trace'){harvests.value=(await api<{items:RecordRow[]}>('/records/harvest?size=200')).items;traces.value=await api('/traces')}}if(s==='finance')finance.value=await api(`/finance?year=${year.value}&include_demo=${includeDemo.value}`);if(s==='guides')guides.value=await api('/crop-guides');if(s==='notifications')todo.value=await api('/notifications');if(s==='reports')reportModule.value=props.modules.find(m=>m.id!=='knowledge')?.id||'';if(s==='market-analysis'){const r=await api<{items:RecordRow[];total:number}>('/records/market?size=200');market.value=r.items;marketTotal.value=r.total;marketKey.value=marketOptions.value[0]||''}})}
watch(()=>props.section,load,{immediate:true})
watch(plot,()=>{batchFilter.value=undefined;rule.crop=String(selectedGrowth.value[0]?.data.crop||'')})
watch(includeDemo,()=>{if(props.section==='market-analysis'&&!marketOptions.value.includes(marketKey.value))marketKey.value=marketOptions.value[0]||''})
async function addRule(){if(!plot.value||!await ruleForm.value?.validate().catch(()=>false))return;await guarded(async()=>{await post('/environment-rules',{plot_id:plot.value,...rule});rules.value=await api('/environment-rules');ElMessage.success('规则已保存；后续环境记录将自动评估')})}
async function toggleRule(r:RecordRow){await guarded(async()=>{await post(`/environment-rules/${r.id}/toggle`,{});rules.value=await api('/environment-rules')})}
async function addHarvest(){if(!await harvestForm.value?.validate().catch(()=>false))return;await guarded(async()=>{await post('/harvests',harvest);harvests.value=(await api<{items:RecordRow[]}>('/records/harvest?size=200')).items;ElMessage.success('采收已登记')})}
async function stock(r:RecordRow){await guarded(async()=>{await post(`/harvests/${r.id}/stock`,{});harvests.value=(await api<{items:RecordRow[]}>('/records/harvest?size=200')).items;traces.value=await api('/traces');ElMessage.success('已入库并生成溯源码')})}
async function publish(t:TraceRow){try{await ElMessageBox.confirm(t.published?'关闭公开后，已有链接将无法访问。':'将公开经营主体、地块名称、批次、采收量及农事类型/日期。请先确认这些内容适合公开。','溯源公开范围');await guarded(async()=>{await post(`/traces/${t.id}/publish`,{});traces.value=await api('/traces')})}catch{}}
async function exportReport(format:string){if(!reportModule.value)return;await guarded(async()=>{await download(`/reports/${reportModule.value}/${format}`,`农知行-${reportModule.value}.${format}`);ElMessage.success('报表已下载')})}
async function changePassword(){if(!await passwordForm.value?.validate().catch(()=>false))return;if(password.repeat!==password.new_password){ElMessage.error('两次新密码不一致');return}await guarded(async()=>{await post('/auth/password',password);Object.assign(password,{old_password:'',new_password:'',repeat:''});ElMessage.success('密码已修改，请重新登录');window.dispatchEvent(new Event('nx-unauthorized'))})}
function go(id:string){router.push('/workspace/'+id)}
const kindNames:Record<string,string>={growth:'生长记录',environment:'环境监测',tasks:'农事任务',feedback:'执行反馈',ai:'AI 分析',harvest:'采收记录',alerts:'环境预警'}
</script>
<template><div class="page-title"><div><h1>{{titles[section]}}</h1><p>从生产记录到经营分析，每项结果都有来源和数据范围</p></div><el-button :loading="busy" @click="load">刷新数据</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<section v-if="['timeline','environment-rules'].includes(section)" class="panel"><el-select v-model="plot" placeholder="选择地块" style="width:300px" @change="section==='timeline'&&guarded(fetchTimeline)"><el-option v-for="l in lands" :key="l.id" :value="l.id" :label="l.title"/></el-select><el-select v-if="section==='timeline'" v-model="batchFilter" clearable placeholder="全部生长批次" style="width:300px;margin-left:12px" @change="guarded(fetchTimeline)"><el-option v-for="g in selectedGrowth" :key="g.id" :value="g.id" :label="g.title"/></el-select></section>
<section v-if="section==='timeline'" class="panel"><el-alert title="时间轴按记录创建时间排序；农事反馈显示最新一次更新。按批次筛选时，环境记录仍显示该地块观测。" :closable="false"/><el-empty v-if="!events.length" description="选择有生产记录的地块查看时间轴"/><el-timeline style="margin-top:24px"><el-timeline-item v-for="e in events" :key="e.key" :timestamp="e.time.replace('T',' ').slice(0,19)"><h3>{{kindNames[e.kind]}} · {{e.title}}</h3><el-tag>{{e.status}}</el-tag><el-tag v-if="e.demo" type="warning">演示记录</el-tag><p class="muted">{{e.detail.date||e.detail.sow_date||''}} {{e.detail.stage||''}} {{e.detail.quantity?e.detail.quantity+' kg':''}}</p><p style="white-space:pre-wrap">{{e.detail.note||e.detail.answer||''}}</p><div v-if="e.kind==='environment'">温度 {{e.detail.temperature}} ℃ · 空气湿度 {{e.detail.humidity}}% · 土壤湿度 {{e.detail.soil}}% · {{e.detail.source}}</div></el-timeline-item></el-timeline></section>
<template v-if="section==='environment-rules'"><section class="panel"><h2>按作物与阶段配置</h2><p class="muted">阈值由用户依据当地农技资料填写，不预设为通用栽培标准。已有观测不追溯触发，新增或修改观测时评估。</p><el-form ref="ruleForm" :model="rule" label-position="top"><div class="defense-grid"><el-form-item label="作物" prop="crop" :rules="required('作物')"><el-input v-model="rule.crop" placeholder="例如 番茄"/></el-form-item><el-form-item label="匹配生长阶段" prop="stage" :rules="required('阶段')"><el-input v-model="rule.stage" placeholder="全部阶段，或与生长记录一致的阶段"/></el-form-item></div><div v-for="m in metrics" :key="m.key" class="defense-grid"><el-form-item :label="m.label+'下限'" :prop="m.key+'_min'" :rules="required('下限')"><el-input-number v-model="rule[`${m.key}_min`]" :min="m.min" :max="m.max" :precision="1" placeholder="依据资料填写"/></el-form-item><el-form-item :label="m.label+'上限'" :prop="m.key+'_max'" :rules="required('上限')"><el-input-number v-model="rule[`${m.key}_max`]" :min="m.min" :max="m.max" :precision="1" placeholder="依据资料填写"/></el-form-item></div><el-form-item label="阈值依据" prop="basis" :rules="required('阈值依据')"><el-input v-model="rule.basis" type="textarea" :maxlength="1000" placeholder="填写资料名称、适用地域、品种及单位口径"/></el-form-item><el-button type="primary" :loading="busy" :disabled="!plot" @click="addRule">保存预警规则</el-button><el-button @click="go('alerts')">查看与处理预警</el-button></el-form></section><section class="panel"><el-table :data="rules"><el-table-column prop="title" label="适用范围"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="配置依据"><template #default="{row}">{{row.data.basis}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link :disabled="busy" @click="toggleRule(row)">{{row.status==='启用'?'停用':'启用'}}</el-button></template></el-table-column></el-table></section></template>
<template v-if="section==='finance'"><section class="panel"><div class="flex"><el-input-number v-model="year" :min="2000" :max="2100"/><el-checkbox v-model="includeDemo">包含演示记录</el-checkbox><el-button :loading="busy" @click="load">核算</el-button><el-button @click="go('expenses')">登记其他支出</el-button><el-button :disabled="busy" @click="guarded(()=>download(`/finance/export/xlsx?year=${year}&include_demo=${includeDemo}`,`经营核算-${year}.xlsx`))">经营 Excel</el-button><el-button :disabled="busy" @click="guarded(()=>download(`/finance/export/pdf?year=${year}&include_demo=${includeDemo}`,`经营核算-${year}.pdf`))">经营 PDF</el-button></div><el-alert v-if="finance" :title="finance.note" :closable="false" style="margin-top:16px"/></section><template v-if="finance"><div class="defense-grid"><section class="panel"><span>登记成本</span><h1>¥ {{finance.cost.toFixed(2)}}</h1></section><section class="panel"><span>出库销售 / 登记差额</span><h1>¥ {{finance.sales.toFixed(2)}} / {{finance.profit.toFixed(2)}}</h1></section></div><section class="panel"><Chart :option="financeChart"/><p>未关联地块：成本 ¥{{finance.unallocated_cost.toFixed(2)}}；销售 ¥{{finance.unallocated_sales.toFixed(2)}}。</p><el-table :data="finance.plots"><el-table-column prop="title" label="地块"/><el-table-column prop="area" label="面积（亩）"/><el-table-column prop="cost" label="成本（元）"/><el-table-column prop="sales" label="销售（元）"/><el-table-column prop="profit" label="登记差额（元）"/><el-table-column label="每亩差额"><template #default="{row}">{{row.profit_per_mu===null?'缺少面积':row.profit_per_mu.toFixed(2)}}</template></el-table-column></el-table></section></template></template>
<template v-if="section==='harvest-trace'"><section class="panel"><h2>关联生产批次登记采收</h2><el-form ref="harvestForm" :model="harvest" :rules="harvestRules" label-position="top"><div class="defense-grid"><el-form-item label="生长批次" prop="growth_id"><el-select v-model="harvest.growth_id" placeholder="选择已关联地块的批次"><el-option v-for="g in growth.filter(g=>g.data.plot_id)" :key="g.id" :value="g.id" :label="g.title"/></el-select></el-form-item><el-form-item label="产品批号" prop="batch"><el-input v-model="harvest.batch" :maxlength="64" placeholder="例如 T-20261002-01"/></el-form-item><el-form-item label="实际采收日期" prop="date"><el-date-picker v-model="harvest.date" type="date" value-format="YYYY-MM-DD" placeholder="选择采收日期"/></el-form-item><el-form-item label="实际重量（kg）" prop="quantity"><el-input-number v-model="harvest.quantity" :min="0.001" :max="100000000" :precision="3"/></el-form-item><el-form-item label="品质等级"><el-select v-model="harvest.grade"><el-option v-for="v in ['A','B','未分级']" :key="v" :value="v" :label="v"/></el-select></el-form-item></div><el-button type="primary" :loading="busy" @click="addHarvest">登记采收</el-button></el-form></section><section class="panel"><h2>采收登记与一次入库</h2><el-table :data="harvests"><el-table-column prop="title" label="采收批次"/><el-table-column prop="status" label="状态"/><el-table-column label="重量"><template #default="{row}">{{row.data.quantity}} kg</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button :disabled="busy||row.status==='已入库'||!row.data.growth_id" @click="stock(row)">入库并生成溯源</el-button></template></el-table-column></el-table><p class="muted">旧台账未关联生长批次时不能自动入库；已入库采收不能修改、删除或重复入库。</p></section><section class="panel"><h2>产品溯源码</h2><el-alert title="默认不公开。公开页仅包含生产摘要，不是官方合格证。二维码指向本机 PC 页面，在其他电脑演示前需配置可访问的地址。" :closable="false"/><el-table :data="traces"><el-table-column label="批次"><template #default="{row}">{{row.snapshot.crop}} / {{row.snapshot.batch}} <el-tag v-if="row.snapshot.demo" type="warning">演示</el-tag></template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.published?'已公开':'未公开'}}</template></el-table-column><el-table-column label="操作" min-width="300"><template #default="{row}"><el-button link :disabled="busy" @click="publish(row)">{{row.published?'关闭公开':'确认公开'}}</el-button><el-button link @click="guarded(()=>download(`/traces/${row.id}/qr`,`溯源码-${row.id}.png`))">下载二维码</el-button><a v-if="row.published" :href="'/trace/'+row.token" target="_blank" rel="noopener">查看 PC 溯源页</a></template></el-table-column></el-table></section></template>
<template v-if="section==='guides'"><section v-for="g in guides" :key="g.crop" class="panel"><el-tag>{{g.crop}}</el-tag><h2>{{g.title}}</h2><p>{{g.scope}}</p><div class="tags"><el-tag v-for="stage in g.stages" :key="stage" type="info">{{stage}}</el-tag></div><ul><li v-for="check in g.checks" :key="check">{{check}}</li></ul><p class="muted">{{g.note}}</p><a :href="g.source" target="_blank" rel="noopener">查阅来源：{{g.source_title}}</a></section></template>
<template v-if="section==='market-analysis'"><section class="panel"><div class="flex"><el-select v-model="marketKey" placeholder="品类 / 地区 / 报价类型 / 等级" style="width:440px"><el-option v-for="k in marketOptions" :key="k" :value="k" :label="k"/></el-select><el-checkbox v-model="includeDemo">包含演示行情</el-checkbox><el-button @click="go('market')">登记报价及来源</el-button></div><p class="muted">仅比较相同品类、地区、报价类型和等级；展示最近读取的 {{market.length}} / {{marketTotal}} 条登记。未接入实时市场报价源。</p><Chart v-if="prices.length" :option="marketChart"/><el-empty v-else description="暂无该口径的报价，请登记有来源的行情"/></section><section class="panel"><h2>销售金额情景测算</h2><p>最新登记：{{latest?.data.date||'暂无'}}；来源：{{latest?.data.source||'未填写'}}。</p><el-input-number v-model="estimateQty" :min="0" :max="100000000" :precision="3"/> kg × {{latest?.data.price||'—'}} 元/kg = <strong>¥ {{estimate.toFixed(2)}}</strong><p class="muted">仅按当前登记单价测算，不含费用损耗，不代表未来价格或承诺收益。</p><el-table :data="prices"><el-table-column label="日期"><template #default="{row}">{{row.data.date}}</template></el-table-column><el-table-column label="元/kg"><template #default="{row}">{{row.data.price}}</template></el-table-column><el-table-column label="来源"><template #default="{row}">{{row.data.source}}</template></el-table-column></el-table></section></template>
<section v-if="section==='notifications'" class="panel"><p class="muted">由未完成农事、未关闭预警和待确认 AI 分析汇总；处理原记录后刷新即可同步。</p><el-empty v-if="!todo.length" description="当前没有待办事项"/><el-table v-else :data="todo"><el-table-column prop="title" label="事项"/><el-table-column prop="status" label="状态"/><el-table-column prop="time" label="更新时间"/><el-table-column label="操作"><template #default="{row}"><el-button link @click="go(row.module)">进入处理</el-button></template></el-table-column></el-table></section>
<section v-if="section==='reports'" class="panel"><h2>按当前权限导出业务台账</h2><el-select v-model="reportModule" placeholder="选择业务模块" style="width:320px"><el-option v-for="m in modules.filter(m=>m.id!=='knowledge')" :key="m.id" :value="m.id" :label="m.title"/></el-select><el-button :loading="busy" @click="exportReport('xlsx')">下载 Excel</el-button><el-button :loading="busy" @click="exportReport('pdf')">下载 PDF</el-button><p class="muted">文件注明记录来源和导出范围；Excel 支持筛选，PDF 保留中文内容。导出操作记录在审计日志。</p></section>
<section v-if="section==='account'" class="panel" style="max-width:650px"><el-form ref="passwordForm" :model="password" :rules="passwordRules" label-position="top"><el-form-item label="原密码" prop="old_password"><el-input v-model="password.old_password" type="password" show-password autocomplete="current-password" placeholder="当前登录账号的密码"/></el-form-item><el-form-item label="新密码" prop="new_password"><el-input v-model="password.new_password" type="password" show-password autocomplete="new-password" placeholder="8–128 个字符"/></el-form-item><el-form-item label="确认新密码" prop="repeat" :rules="required('确认新密码')"><el-input v-model="password.repeat" type="password" show-password autocomplete="new-password" placeholder="再次填写新密码"/></el-form-item><p class="muted">修改成功后，已有登录会话失效，需要重新登录。</p><el-button type="primary" :loading="busy" @click="changePassword">保存新密码</el-button></el-form></section>
</template>
<style scoped>.defense-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.defense-grid .el-select,.defense-grid .el-input-number,.defense-grid .el-date-editor{width:100%}.panel{margin-bottom:20px}li{line-height:2}a{color:var(--el-color-primary)}@media(max-width:760px){.defense-grid{grid-template-columns:minmax(0,1fr)}.panel>.el-select{width:100%!important;margin:0 0 12px!important}.panel>.el-button{margin-bottom:8px}}</style>


